fn get_min_val(a: &Vec<i8>) -> i8 {
    // Since the array is non-empty, unwrap is safe here
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // Since the array is non-empty, unwrap is safe here
    *a.iter().max().unwrap()
}

fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    // q is in [0, 100] as per problem statement

    // Handle boundary cases directly
    if q == 0 {
        return get_min_val(&a);
    }
    if q == 100 {
        return get_max_val(&a);
    }

    // Sort the array to find quantiles
    a.sort_unstable();

    let n = a.len();

    // Calculate the quantile index as a floating point:
    // Example: q=25, n=4 elements -> index = 25/100*(4-1) = 0.75
    // We'll round down to index = 0 for integer index
    let qf = q as f64 / 100.0;
    let pos = qf * ((n - 1) as f64);

    // Use floor to get index; quantile indexing by nearest rank or lower
    let idx = pos.floor() as usize;

    a[idx]
}